// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    address creator;

    function setUp() public {
        c = new Wallet();
        creator = address(this);
    }

    function testFuzz_property(uint256 amount, address funder, address to) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(funder != address(0) && funder != creator);
        vm.assume(to != address(0) && to != creator);
        vm.assume(to != address(c));

        vm.deal(funder, amount);
        vm.prank(funder);
        c.deposit{value: amount}();
        require(address(c).balance == amount);

        uint256 creatorBefore = creator.balance;

        vm.prank(creator);
        c.migrateTo(to);

        // The migration must never pay the caller: creator's balance is unchanged
        // (the mutant sends the whole contract balance to msg.sender instead).
        assertTrue(creator.balance == creatorBefore);
    }
}
